package com.franco.desco.adapter.in.web.pricing;import com.franco.desco.adapter.in.security.JwtSessionIdentityResolver;import com.franco.desco.adapter.in.web.common.*;import com.franco.desco.adapter.in.web.common.idempotency.IdempotentOperation;import com.franco.desco.adapter.in.web.common.pagination.PageResponse;import com.franco.desco.adapter.in.web.openapi.OpenApiConstants;import com.franco.desco.application.pricing.*;import com.franco.desco.application.pricing.port.in.PricingUseCase;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController@RequestMapping("/api/v1/condiciones-precios")@Tag(name="Condiciones y precios",description="Condiciones comerciales y versionado de precios.")@SecurityRequirement(name=OpenApiConstants.BEARER_AUTH)@Validated public class PricingController{private final PricingUseCase u;private final PricingWebMapper map;private final ApiResponseFactory res;private final ClientRequestContextResolver meta;private final JwtSessionIdentityResolver ids;public PricingController(PricingUseCase u,PricingWebMapper map,ApiResponseFactory res,ClientRequestContextResolver meta,JwtSessionIdentityResolver ids){this.u=u;this.map=map;this.res=res;this.meta=meta;this.ids=ids;}
 @GetMapping("/condiciones")@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_LISTAR')")@Operation(operationId="preciosCondicionesListar",summary="Listar condiciones comerciales")public ResponseEntity<ApiResponse<PageResponse<PricingResponses.Condition>>>conditions(@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.conditions(map.conditions(pagina,tamano),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @PostMapping("/condiciones")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_CREAR')")@Operation(operationId="preciosCondicionesCrear",summary="Crear condición comercial")public ResponseEntity<ApiResponse<PricingResponses.Created>>createCondition(@Valid@RequestBody PricingRequests.CreateCondition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.createCondition(new PricingCommands.CreateCondition(q.modalidadVentaId(),q.codigo(),q.nombre(),q.descripcion(),q.pesoMinimoG(),q.pesoMaximoG()),ids.resolve(a),meta.resolve(r)),r,PricingResponses.Created::new);}
 @PutMapping("/condiciones/{id}")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_ADMINISTRAR')")@Operation(operationId="preciosCondicionesEditar",summary="Editar condición comercial")public ResponseEntity<ApiResponse<Void>>updateCondition(@PathVariable Long id,@Valid@RequestBody PricingRequests.UpdateCondition q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.updateCondition(new PricingCommands.UpdateCondition(id,q.nombre(),q.descripcion(),q.pesoMinimoG(),q.pesoMaximoG()),ids.resolve(a),meta.resolve(r)),r);}
 @PostMapping("/condiciones/{id}/deshabilitar")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_RETIRAR')")@Operation(operationId="preciosCondicionesDeshabilitar",summary="Deshabilitar condición comercial")public ResponseEntity<ApiResponse<Void>>disableCondition(@PathVariable Long id,@Valid@RequestBody PricingRequests.Disable q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.disableCondition(new PricingCommands.DisableCondition(id,q.motivo()),ids.resolve(a),meta.resolve(r)),r);}
 @GetMapping("/precios")@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_LISTAR')")@Operation(operationId="preciosListar",summary="Listar precios comerciales")public ResponseEntity<ApiResponse<PageResponse<PricingResponses.Price>>>prices(@RequestParam(required=false)Long campaniaVentaId,@RequestParam(required=false)Long operativoVentaId,@RequestParam(required=false)Integer variedadPaltaId,@RequestParam(required=false)Long condicionComercialId,@RequestParam(defaultValue="1")@Min(1)int pagina,@RequestParam(defaultValue="20")@Min(1)@Max(100)int tamano,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.prices(map.prices(pagina,tamano,campaniaVentaId,operativoVentaId,variedadPaltaId,condicionComercialId),ids.resolve(a),meta.resolve(r)),r,p->PageResponse.from(p,map::response));}
 @PostMapping("/precios")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_CREAR')")@Operation(operationId="preciosCrear",summary="Crear precio comercial")public ResponseEntity<ApiResponse<PricingResponses.Created>>createPrice(@Valid@RequestBody PricingRequests.CreatePrice q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.createPrice(new PricingCommands.CreatePrice(q.campaniaVentaId(),q.operativoVentaId(),q.variedadPaltaId(),q.condicionComercialId(),q.precio(),q.moneda(),q.unidadMedida(),q.fechaVigenciaDesde()),ids.resolve(a),meta.resolve(r)),r,PricingResponses.Created::new);}
 @PostMapping("/precios/{id}/version")@IdempotentOperation@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_EDITAR')")@Operation(operationId="preciosVersionar",summary="Crear nueva versión de precio")public ResponseEntity<ApiResponse<PricingResponses.Created>>version(@PathVariable Long id,@Valid@RequestBody PricingRequests.VersionPrice q,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.versionPrice(new PricingCommands.VersionPrice(id,q.precio(),q.fechaVigenciaDesde()),ids.resolve(a),meta.resolve(r)),r,PricingResponses.Created::new);}
 @GetMapping("/precios/{id}/historial")@PreAuthorize("@permissionGuard.has(authentication,'PRECIOS_VER')")@Operation(operationId="preciosHistorial",summary="Ver historial de un precio")public ResponseEntity<ApiResponse<List<PricingResponses.PriceVersion>>>history(@PathVariable Long id,@Parameter(hidden=true)JwtAuthenticationToken a,@Parameter(hidden=true)HttpServletRequest r){return res.from(u.history(new PricingCommands.PriceHistory(id),ids.resolve(a),meta.resolve(r)),r,l->l.stream().map(map::response).toList());}}
